import Resizable from "@marko-ui/shadcn/ui/resizable/resizable.marko";

static const PANELS = [
  { id: "header", defaultSize: 25 },
  { id: "content", defaultSize: 75 },
];

<Resizable|panel| panels=PANELS orientation="vertical" class="min-h-[200px] max-w-md rounded-lg border md:min-w-[450px]">
  <div class="flex h-full items-center justify-center p-6">
    <span class="font-semibold">${panel.id === "header" ? "Header" : "Content"}</span>
  </div>
</Resizable>

import Resizable from "@marko-ui/shadcn/ui/resizable/resizable.marko";

static const PANELS = [
  { id: "sidebar", defaultSize: 25, minSize: 15 },
  { id: "content", defaultSize: 75, minSize: 30 },
];

<Resizable|panel| panels=PANELS class="min-h-[200px] max-w-md rounded-lg border md:min-w-[450px]">
  <div class="flex h-full items-center justify-center p-6">
    <span class="font-semibold">${panel.id === "sidebar" ? "Sidebar" : "Content"}</span>
  </div>
</Resizable>
